import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA kernel for element-wise addition (float)
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=[],
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# Custom CUDA kernel for exclusive cumulative sum along a dimension (float)
# ----------------------------------------------------------------------
exclusive_cumsum_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void exclusive_cumsum_kernel(const float* input, float* output, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float sum = 0.0f;
        for (int i = 0; i < idx; ++i) {
            sum += input[i];
        }
        output[idx] = sum;
    }
}

torch::Tensor exclusive_cumsum_cuda(torch::Tensor input) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    exclusive_cumsum_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

exclusive_cumsum = load_inline(
    name="exclusive_cumsum",
    cpp_sources=[],
    cuda_sources=exclusive_cumsum_kernel_source,
    functions=["exclusive_cumsum_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add
        self.exclusive_cumsum = exclusive_cumsum

    def forward(self, x):
        """
        Compute the exclusive cumulative sum along dimension `self.dim` (here dim=1)
        for each row of `x`, excluding the last feature column.
        The result is concatenated with a zero tensor of the same shape.
        """
        batch_size = x.size(0)
        num_features = x.size(1)

        out = torch.zeros_like(x)

        for b in range(batch_size):
            row = x[b]                     # shape (num_features,)
            flat_row = row.flatten().float()   # numpy array
            n_elements = flat_row.size(0) - 1  # exclude the last feature

            if n_elements > 0:
                cumsum_excl = self.exclusive_cumsum.elementexclusive_cumsum_cuda(torch.from_numpy(flat_row))
            else:
                cumsum_excl = torch.zeros_like(flat_row)

            out[b] = cumsum_excl.reshape(num_features, 1) + flat_row[-1] * 0.0
        return out
